// FUNCTION: BFME2 0x00486327 size=387 name=?onDie@CrushDie@@UAEXPBVDamageInfo@@@Z evidence=N:ledger tier=A
void CrushDie::onDie(const DamageInfo *damageInfo)
{
	if (!isDieApplicable(damageInfo))
		return;
	if (damageInfo->in.m_damageType != DAMAGE_CRUSH)
		return;

	Object *damageDealer = TheGameLogic->findObjectByID(damageInfo->in.m_sourceID);
	CrushEnum crushType = damageDealer ? crushLocationCheck(damageDealer, getObject()) : TOTAL_CRUSH;
	if (crushType != NO_CRUSH)
	{
		if (getCrushDieModuleData()->m_crushSounds[crushType].referent != 0)
		{
			if (GetGameLogicRandomValue(0, 99, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Die\\CrushDie.cpp", 167) < getCrushDieModuleData()->m_crushSoundPercent[crushType])
			{
				AudioEventRTS crushSound(getCrushDieModuleData()->m_crushSounds[crushType], 0);
				crushSound.setObjectID(getObject()->getID());
				TheAudio->addAudioEvent(&crushSound);
			}
		}
		Object *me = getObject();
		if (me)
		{
			me->getBodyModule()->setFrontCrushed(crushType == TOTAL_CRUSH || crushType == FRONT_END_CRUSH);
			me->getBodyModule()->setBackCrushed(crushType == TOTAL_CRUSH || crushType == BACK_END_CRUSH);
			ModelConditionFlags newCrushed;
			newCrushed.set(1, crushType == TOTAL_CRUSH || crushType == FRONT_END_CRUSH);
			newCrushed.set(2, crushType == TOTAL_CRUSH || crushType == BACK_END_CRUSH);
			me->rva0028CFB2((const int *)&ModelConditionFlags(ModelConditionFlags::kInit, 2, 1), (const int *)&newCrushed);
		}
	}
}


